{
  "name": "model-router",
  "version": "0.2.0",
  "description": "Routes each turn to the cheapest model + effort that fits the task (Haiku 5.5 → Sonnet 5.5 → Opus 5.5 → Fable 5.1) and shows the ladder in a side pane.",
  "author": {
    "name": "Troy Lorents"
  },
  "types": "./types/index.d.ts",
  "userConfig": {
    "classifier": {
      "type": "string",
      "title": "Classifier",
      "description": "haiku: a ~1s Haiku 5.5 call grades each prompt (heuristics as fallback). heuristic: keyword/shape scoring only, zero cost.",
      "options": [
        "haiku",
        "heuristic"
      ],
      "default": "haiku"
    },
    "ceiling": {
      "type": "string",
      "title": "Highest model allowed",
      "description": "Cost cap: the router never picks a model above this one.",
      "options": [
        "haiku",
        "sonnet",
        "opus",
        "fable"
      ],
      "default": "fable"
    },
    "stickiness": {
      "type": "number",
      "title": "Downgrade stickiness (rungs)",
      "description": "While the prompt cache is warm, only step down the ladder when the new pick is at least this many rungs lower. Upgrades always apply.",
      "default": 3
    }
  }
}

